namespace org.accordproject.carrentalagreement

concept LessorParty {
  o String companyName
  o String address
  o String phoneNumber
}

concept LesseeParty {
  o String fullName
  o String address
  o String phoneNumber
}

concept VehicleDetails {
  o String plateNumber
