  o PrepaymentTerms prepaymentTerms
  o RemedialsTerms remedialsTerms
  o UsuryCap usuryCap
  o AmendmentTerms amendmentTerms
  o AssignmentTerms assignmentTerms
  o String governingLaw
  o Boolean entireAgreement
  o Boolean counterpartsExecution
}

